  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Tolvaptan, a benzamide-type drug with aromatic amide and lipophilic substituents, has mean absolute oral bioavailability of 56% in healthy subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Venadaparib, which contains a benzamide and an indazole heterocycle, showed good oral bioavailability in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Imidafenacin, an amide-containing heteroaromatic drug, has absolute oral bioavailability of 57.8% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "ACT-1004-1239, an amide-containing heteroaromatic compound, has absolute bioavailability of 53% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Bromazepam, a pyridine-containing heteroaromatic drug, has absolute bioavailability of 86%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Lenvatinib, an amide/heteroaromatic drug, has absolute bioavailability of about 85%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ilomastat, a peptidomimetic hydroxamate, showed poor oral bioavailability; however, the query lacks the polar hydroxamate/peptide backbone, so this contradictory evidence is outweighed.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer human absolute-bioavailability measurements for structurally related amide/heteroaromatic drugs (tolvaptan 56%, imidafenacin 57.8%, ACT-1004-1239 53%, bromazepam 86%, lenvatinib ~85%, venadaparib good) strongly support F≥20% for the query. The only negative analogue is a polar peptidomimetic hydroxamate unlike the query. Prediction: high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule.",
    "The negative ilomastat result is qualitative and not threshold-specific; its structural class differs from the query.",
    "Fasted-state-specific PK for the query is not directly available; most evidence is from standard oral dosing in healthy subjects."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

